package com.yuegang.zhihui.admin.application;import com.yuegang.zhihui.admin.api.*;import java.time.*;import java.util.*;import org.springframework.web.client.RestClient;public final class AdminDashboardService{private final Map<String,String>urls;public AdminDashboardService(String encoded){var map=new LinkedHashMap<String,String>();for(String item:encoded.split(",")){int p=item.indexOf('=');if(p>0)map.put(item.substring(0,p),item.substring(p+1));}urls=Map.copyOf(map);}public AdminDashboardView dashboard(){var statuses=new ArrayList<AdminDashboardView.ServiceStatus>();urls.forEach((name,url)->{long start=System.nanoTime();String status="DOWN";try{Map<?,?>r=RestClient.create().get().uri(url).retrieve().body(Map.class);if(r!=null)status=Objects.toString(r.get("status"),"UNKNOWN");}catch(RuntimeException ignored){status="DOWN";}statuses.add(new AdminDashboardView.ServiceStatus(name,status,(System.nanoTime()-start)/1_000_000));});return new AdminDashboardView(statuses,List.of(),OffsetDateTime.now(ZoneOffset.UTC));}}
